                    let revision = upnp_mappings.revision();
                    let mut mappings = upnp_mappings.clone();
                    let tx = upnp_maintain_result_tx.clone();
                    upnp_maintain_in_flight = true;
                    upnp_maintain_started_at = Some(tokio::time::Instant::now());
